-- Base Oficial Completa dos 184 Prefeitos do Ceará (2025-2028)
-- Tripla Validação: TSE 2024 / APRECE / G1 & Diário do Nordeste
-- ============================================================

-- 1. Compatibilidade ceara_municipalities (id SERIAL e ajuste Catunda)
ALTER TABLE ceara_municipalities ADD COLUMN IF NOT EXISTS id SERIAL;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'ceara_municipalities_id_key'
  ) THEN
    ALTER TABLE ceara_municipalities ADD CONSTRAINT ceara_municipalities_id_key UNIQUE (id);
  END IF;
END $$;

UPDATE ceara_municipalities
SET name = 'Catunda', macro_region = 'Sertão dos Crateús'
WHERE ibge_code = '2312759';

-- 2. Compatibilidade e novas colunas em municipal_authorities
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_name = 'municipal_authorities' AND column_name = 'municipality_id'
  ) THEN
    ALTER TABLE municipal_authorities ADD COLUMN municipality_id INTEGER REFERENCES ceara_municipalities(id) ON DELETE SET NULL;
  END IF;
END $$;
ALTER TABLE municipal_authorities ADD COLUMN IF NOT EXISTS role TEXT DEFAULT 'prefeito';
ALTER TABLE municipal_authorities ADD COLUMN IF NOT EXISTS ballot_name TEXT;
ALTER TABLE municipal_authorities ADD COLUMN IF NOT EXISTS vice_mayor TEXT;
ALTER TABLE municipal_authorities ADD COLUMN IF NOT EXISTS mayor_mandate TEXT DEFAULT '2025-2028';
ALTER TABLE municipal_authorities ADD COLUMN IF NOT EXISTS phone TEXT;
ALTER TABLE municipal_authorities ADD COLUMN IF NOT EXISTS whatsapp TEXT;
ALTER TABLE municipal_authorities ADD COLUMN IF NOT EXISTS votes_2024 INTEGER;
ALTER TABLE municipal_authorities ADD COLUMN IF NOT EXISTS percentage_2024 NUMERIC(5,2);
ALTER TABLE municipal_authorities ADD COLUMN IF NOT EXISTS is_reelected BOOLEAN DEFAULT false;
ALTER TABLE municipal_authorities ADD COLUMN IF NOT EXISTS electoral_history JSONB DEFAULT '{}'::jsonb;
ALTER TABLE municipal_authorities ADD COLUMN IF NOT EXISTS verification_sources TEXT[] DEFAULT '{}';

-- Flexibiliza constraints de validação legadas
ALTER TABLE municipal_authorities DROP CONSTRAINT IF EXISTS municipal_authorities_role_type_check;
ALTER TABLE municipal_authorities DROP CONSTRAINT IF EXISTS municipal_authorities_allied_status_check;

-- Índice único para permitir UPSERT idempotente de autoridades por mandato
CREATE UNIQUE INDEX IF NOT EXISTS idx_mun_auth_ibge_role ON municipal_authorities (municipality_ibge, role_type, mandate_period);

