-- 4. Associação de chave estrangeira municipality_id com ceara_municipalities
UPDATE municipal_authorities ma
SET municipality_id = cm.id
FROM ceara_municipalities cm
WHERE cm.ibge_code = ma.municipality_ibge
  AND (ma.municipality_id IS NULL OR ma.municipality_id <> cm.id);
